import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3 } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry } = THREE;

  const group = new Group();
  const timelines = [];
  const materials = [];
  const geometries = [];

  // Timing calculations (fallback if primitive doesn't return timeline)
  const heroText = 'TIME, MACHINED.';
  const heroCharCount = heroText.length; // 15 chars
  const kineticDuration = (heroCharCount - 1) * 60 + 700; // 1540ms glyph animation
  const settleDuration = 900; // 900ms settle
  const fallbackTotalDuration = (kineticDuration + settleDuration) / 1000; // seconds

  // 1. Backdrop plane (7 x 5.5 at z=-1.5) with vertical gradient
  const backdropGeom = new PlaneGeometry(7, 5.5);
  const backdropMat = new MeshBasicNodeMaterial();

  const colorTop = vec3(0x0b / 255, 0x0b / 255, 0x10 / 255); // #0b0b10
  const colorBot = vec3(0x13 / 255, 0x13 / 255, 0x1a / 255); // #13131a
  const uvNode = uv();
  backdropMat.colorNode = mix(colorTop, colorBot, uvNode.y);

  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -1.5;
  group.add(backdrop);

  geometries.push(backdropGeom);
  materials.push(backdropMat);

  // 2. Caption kicker "NOVA ATELIER / CALIBRE PROGRAM" at y=1.15
  const captionText = ctx.fontAtlas.createText('NOVA ATELIER / CALIBRE PROGRAM', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 2.16 // 0.12 * 18
  });
  captionText.position.y = 1.15;
  group.add(captionText);

  // 3. Hero text group with per-word z-offsets for parallax depth
  const heroGroup = new Group();
  heroGroup.scale.set(1.04, 1.04, 1.04); // Start at 1.04 for weighted-settle to 1.0

  const heroWord1 = ctx.fontAtlas.createText('TIME,', {
    fontSize: 124,
    color: '#e8ecf2',
    align: 'right',
    letterSpacingPx: -1.24 // -0.01 * 124
  });
  heroWord1.position.set(-0.5, 0.4, 0.12); // Front depth
  heroGroup.add(heroWord1);

  const heroWord2 = ctx.fontAtlas.createText('MACHINED.', {
    fontSize: 124,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: -1.24
  });
  heroWord2.position.set(0.5, 0.4, -0.12); // Back depth
  heroGroup.add(heroWord2);

  group.add(heroGroup);

  // 4. Subhead text "Every calibre begins as a solid billet." at y=-0.65
  const subheadText = ctx.fontAtlas.createText('Every calibre begins as a solid billet.', {
    fontSize: 40,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.8, // 0.02 * 40
    maxWidthPx: 800
  });
  const subheadTargetY = -0.65;
  subheadText.position.y = subheadTargetY + 0.2; // Start higher for fade-up

  // Initialize opacity = 0 on child materials
  subheadText.traverse(child => {
    if (child.material) {
      child.material.transparent = true;
      child.material.opacity = 0;
    }
  });

  group.add(subheadText);

  // 5. Accent underline rule (2.6 x 0.045, #ff2a38 emissive at y=-0.05)
  const accentGeom = new PlaneGeometry(2.6, 0.045);
  const accentMat = new MeshBasicNodeMaterial();
  accentMat.color.setHex(0xff2a38);
  accentMat.emissive.setHex(0xff2a38);
  accentMat.emissiveIntensity = 1.2;

  const accentLine = new Mesh(accentGeom, accentMat);
  accentLine.position.y = -0.05;
  accentLine.scale.x = 0; // Start collapsed, scales to 1.0
  group.add(accentLine);

  geometries.push(accentGeom);
  materials.push(accentMat);

  // 6. Apply kinetic-text primitive (per-glyph entrance + weighted-settle)
  let kineticCleanup = null;
  let totalKineticDuration = fallbackTotalDuration;

  const kineticResult = ctx.primitives['kinetic-text'](heroGroup, {
    staggerMs: 60,
    riseUnits: 0.35
  });

  if (kineticResult && kineticResult.cleanup) {
    kineticCleanup = kineticResult.cleanup;
  }
  if (kineticResult && kineticResult.timeline && typeof kineticResult.timeline.duration === 'function') {
    totalKineticDuration = kineticResult.timeline.duration();
  }

  // 7. Underline animation: scaleX 0 to 1 starting 120ms after kinetic completes
  const underlineDelay = totalKineticDuration + 0.12;
  const underlineTl = gsap.timeline({ delay: underlineDelay });
  underlineTl.to(accentLine.scale, {
    x: 1.0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
  });
  timelines.push(underlineTl);

  // 8. Subhead fade-up: opacity 0→1, y +0.2→0, starting when kinetic completes
  const subheadDelay = totalKineticDuration;
  const subheadAnimObj = { y: subheadTargetY + 0.2, opacity: 0 };
  const subheadTl = gsap.to(subheadAnimObj, {
    y: subheadTargetY,
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
    delay: subheadDelay,
    onUpdate: function() {
      subheadText.position.y = subheadAnimObj.y;
      subheadText.traverse(child => {
        if (child.material) {
          child.material.opacity = subheadAnimObj.opacity;
        }
      });
    }
  });
  timelines.push(subheadTl);

  // Cleanup
  group.userData.cleanup = function() {
    timelines.forEach(tl => {
      if (tl && tl.kill) {
        tl.kill();
      }
    });
    if (kineticCleanup) {
      kineticCleanup();
    }
    materials.forEach(mat => mat.dispose());
    geometries.forEach(geom => geom.dispose());
  };

  return group;
}
